func:
 // =====================================
 // LEITURA E VALIDAÇÃO DOS DADOS
 // =====================================

var tensao;
var evento = msg.evento || "normal";

if (
    typeof msg.payload === "number" ||
    (typeof msg.payload === "string" && msg.payload.trim() !== "")
) {
    tensao = Number(msg.payload);

} else if (typeof msg.payload === "object" && msg.payload !== null) {
    tensao = Number(
        msg.payload.tensao !== undefined
            ? msg.payload.tensao
            : msg.payload.payload
    );

    evento = msg.payload.evento || evento;

} else {
    try {
        var dados = JSON.parse(msg.payload);

        if (typeof dados === "object" && dados !== null) {
            tensao = Number(dados.tensao);
            evento = dados.evento || evento;
        } else {
            tensao = Number(dados);
        }
    } catch (err) {
        node.warn("Mensagem ignorada: formato de tensão inválido.");
        return null;
    }
}

// Não transforma leituras inválidas em uma tensão normal
if (!Number.isFinite(tensao)) {
    node.warn("Mensagem ignorada: tensão inválida.");
    return null;
}

// =====================================
// PADRONIZAÇÃO DOS EVENTOS
// =====================================

evento = String(evento).trim().toLowerCase();

switch (evento) {
    case "critica_inferior":
    case "precaria_inferior":
        evento = "afundamento";
        break;

    case "critica_superior":
    case "precaria_superior":
        evento = "sobretensao";
        break;

    case "harmônica":
        evento = "harmonica";
        break;

    case "transitório":
        evento = "transitorio";
        break;

    case "normal":
        evento = "normal";
        break;
}

var ehHarmonica = (evento === "harmonica");

msg.tensao = tensao;
msg.evento = evento;

// =====================================
// LEITURA DO ESTADO ANTERIOR
// =====================================

var estado_anterior = context.get("estado") || "ADEQUADA";

// =====================================
// CLASSIFICAÇÃO E HISTERESE
// =====================================

if (estado_anterior === "CRÍTICA") {

    // Sai da condição crítica apenas na faixa segura
    if (tensao >= 117 && tensao <= 133) {
        estado_anterior = "ADEQUADA";
    }

} else if (estado_anterior === "PRECÁRIA") {

    if (tensao > 135 || tensao < 110) {
        estado_anterior = "CRÍTICA";
    } else if (tensao >= 117 && tensao <= 133) {
        estado_anterior = "ADEQUADA";
    }

} else {

    if (tensao > 135 || tensao < 110) {
        estado_anterior = "CRÍTICA";
    } else if (
        (tensao > 133 && tensao <= 135) ||
        (tensao >= 110 && tensao < 117)
    ) {
        estado_anterior = "PRECÁRIA";
    }
}

// =====================================
// TEMPO EM ESTADO CRÍTICO
// =====================================

var inicioCritico = context.get("inicioCritico");
var tempoCritico = 0;

var criticoPRODIST = (estado_anterior === "CRÍTICA");

// Entrada na condição crítica
if (criticoPRODIST && !inicioCritico) {
    inicioCritico = Date.now();

    context.set("inicioCritico", inicioCritico);
    flow.set("inicioTemporizacao", inicioCritico);
}

// Permanência na condição crítica
if (criticoPRODIST && inicioCritico) {
    tempoCritico = (Date.now() - inicioCritico) / 1000;
}

// Saída da condição crítica
if (!criticoPRODIST && inicioCritico) {
    context.set(
        "ultimoTempoCritico",
        (Date.now() - inicioCritico) / 1000
    );

    context.set("inicioCritico", null);
    flow.set("inicioTemporizacao", null);
}

msg.tempoCritico = tempoCritico.toFixed(2);

msg.ultimoTempoCritico = Number(
    context.get("ultimoTempoCritico") || 0
).toFixed(2);

// =====================================
// ESTADO E SOLICITAÇÃO DE PROTEÇÃO
// =====================================

context.set("estado", estado_anterior);

msg.payload = estado_anterior;
msg.estado = estado_anterior;

// A proteção depende da tensão classificada,
// não exclusivamente do rótulo do evento.
msg.trip = (estado_anterior === "CRÍTICA");

// =====================================
// FORMATAÇÃO DO EVENTO PARA O DASHBOARD
// =====================================

switch (evento) {
    case "normal":
        msg.evento = "Normal";
        break;

    case "afundamento":
        msg.evento = "Afundamento";
        break;

    case "sobretensao":
        msg.evento = "Sobretensão";
        break;

    case "harmonica":
        msg.evento = "Harmônica";
        break;

    case "transitorio":
        msg.evento = "Transitório";
        break;

    case "ruido":
        msg.evento = "Ruído";
        break;

    default:
        msg.evento = evento;
}

msg.info =
    "Evento: " + msg.evento +
    " | Tensão: " + tensao.toFixed(2) + " V";

// Estado do disjuntor virtual
if (flow.get("tripado") === true) {
    msg.disjuntor = "ABERTO";
} else {
    msg.disjuntor = "FECHADO";
}

// =====================================
// CONTADORES DE EVENTOS
// =====================================

// Conta a transição entre classes de evento.
// Não representa necessariamente cada ocorrência física.
var ultimoEvento = flow.get("ultimoEvento") || "normal";

if (evento !== ultimoEvento) {
    switch (evento) {
        case "afundamento":
            flow.set(
                "cont_afundamento",
                (flow.get("cont_afundamento") || 0) + 1
            );
            break;

        case "sobretensao":
            flow.set(
                "cont_sobretensao",
                (flow.get("cont_sobretensao") || 0) + 1
            );
            break;

        case "transitorio":
            flow.set(
                "cont_transitorio",
                (flow.get("cont_transitorio") || 0) + 1
            );
            break;

        case "harmonica":
            flow.set(
                "cont_harmonica",
                (flow.get("cont_harmonica") || 0) + 1
            );
            break;
    }

    flow.set("ultimoEvento", evento);
}

msg.cont_afundamento = flow.get("cont_afundamento") || 0;
msg.cont_sobretensao = flow.get("cont_sobretensao") || 0;
msg.cont_transitorio = flow.get("cont_transitorio") || 0;
msg.cont_harmonica = flow.get("cont_harmonica") || 0;

return msg;

// =====================================
// RESET
// =====================================

if (msg.topic === "reset") {

    flow.set("tripado", false);
    flow.set("inicioTrip", null);

    msg.payload = "DISJUNTOR FECHADO";
    return msg;
}

// =====================================
// CALCULA O TEMPO ATÉ A ATUAÇÃO
// =====================================

if (msg.payload === true) {

    flow.set("tripado", true);

    var inicio = flow.get("inicioTemporizacao");

    node.warn("Início da temporização: " + inicio);

    if (inicio) {

        var tempo =
            (Date.now() - inicio) / 1000;

        flow.set("ultimoTempoTrip", tempo);

        flow.set("inicioTemporizacao", null);

    }
}

// =====================================
// ESTADO DO DISJUNTOR
// =====================================

if (flow.get("tripado") === true) {

    msg.payload = "DISJUNTOR ABERTO";

} else {

    msg.payload = "DISJUNTOR FECHADO";

}

// Envia o último tempo medido
msg.tempoTrip = (flow.get("ultimoTempoTrip") || 0).toFixed(2);

return msg;

const TAMANHO_JANELA = 3;

let historico = context.get("historicoTensao") || [];

// Extrai a tensão de forma segura
let tensaoAtual;

if (typeof msg.payload === "number") {
    tensaoAtual = msg.payload;
} else if (typeof msg.payload === "string") {
    tensaoAtual = Number(msg.payload);
} else if (msg.payload && typeof msg.payload === "object") {
    tensaoAtual = Number(msg.payload.tensao);
} else {
    return null;
}

// Não processa valores inválidos
if (!Number.isFinite(tensaoAtual)) {
    return null;
}

// Atualiza a janela da média móvel
historico.push(tensaoAtual);

if (historico.length > TAMANHO_JANELA) {
    historico.shift();
}

context.set("historicoTensao", historico);

// Calcula a média
const media = historico.reduce((soma, valor) => soma + valor, 0)
    / historico.length;

// Preserva os campos originais e fornece a tensão filtrada
msg.sinal_bruto = tensaoAtual;
msg.tensao_filtrada = media;
msg.payload = media;

return msg;

let ultimo = flow.get("ultimo_estado");

if (msg.estado !== ultimo) {

    flow.set("ultimo_estado", msg.estado);

    let agora = new Date().toLocaleTimeString();

    msg.payload =
        agora + " - " +
        msg.estado;

    return msg;
}

return null;

let dados;

// Converte o JSON recebido
if (typeof msg.payload === "object") {
    dados = msg.payload;
} else {
    dados = JSON.parse(msg.payload);
}

// Variáveis principais
msg.tensao = Number(dados.tensao);
msg.evento = dados.evento || "normal";

// Payload principal
msg.payload = msg.tensao;

// Informações auxiliares
msg.timestamp = new Date().toISOString();

return msg;

var historico = flow.get("historico") || [];

function atualizarEstatisticas(nomeEvento, duracao){

    var qtd = flow.get("qtd_" + nomeEvento) || 0;
    var tempo = flow.get("tempo_" + nomeEvento) || 0;
    var maior = flow.get("maior_" + nomeEvento) || 0;

    qtd++;
    tempo += duracao;

    if(duracao > maior){
        maior = duracao;
    }

    flow.set("qtd_" + nomeEvento, qtd);
    flow.set("tempo_" + nomeEvento, tempo);
    flow.set("maior_" + nomeEvento, maior);

}
var eventoAtual = context.get("eventoAtual") || null;

// Se for um evento diferente de Normal
if (msg.evento !== "Normal") {

    // Não existe evento em andamento
    if (eventoAtual === null) {

        context.set("eventoAtual", {
            evento: msg.evento,
            estado: msg.estado,
            tensao: msg.tensao,
            disjuntor: msg.disjuntor,
            inicio: Date.now()
        });

        return null;
    }

    // Mudou de evento (Afundamento -> Harmônica, etc.)
    if (eventoAtual.evento !== msg.evento) {

        var duracao = ((Date.now() - eventoAtual.inicio) / 1000);

        historico.unshift({

            datahora: new Date(eventoAtual.inicio).toLocaleString("pt-BR"),
            evento: eventoAtual.evento,
            estado: eventoAtual.estado,
            duracao: duracao.toFixed(2) + " s",
            tensao: eventoAtual.tensao.toFixed(2) + " V",
            disjuntor: eventoAtual.disjuntor

        });

switch(eventoAtual.evento){

    case "Afundamento":
        atualizarEstatisticas("afundamento", duracao);
        break;

    case "Sobretensão":
        atualizarEstatisticas("sobretensao", duracao);
        break;

    case "Transitório":
        atualizarEstatisticas("transitorio", duracao);
        break;

    case "Harmônica":
        atualizarEstatisticas("harmonica", duracao);
        break;
        }

        historico = historico.slice(0,20);

        flow.set("historico", historico);

        // inicia o novo evento
        context.set("eventoAtual", {

            evento: msg.evento,
            estado: msg.estado,
            tensao: msg.tensao,
            disjuntor: msg.disjuntor,
            inicio: Date.now()

        });

        msg.payload = historico;
        return msg;
    }

    // Continua o mesmo evento
    return null;
}

// Se voltou para Normal e havia um evento ativo
if (msg.evento === "Normal" && eventoAtual !== null) {

    var duracao = ((Date.now() - eventoAtual.inicio) / 1000);

    historico.unshift({

        datahora: new Date(eventoAtual.inicio).toLocaleString("pt-BR"),
        evento: eventoAtual.evento,
        estado: eventoAtual.estado,
        duracao: duracao.toFixed(2) + " s",
        tensao: eventoAtual.tensao.toFixed(2) + " V",
        disjuntor: eventoAtual.disjuntor

    });

    switch(eventoAtual.evento){

    case "Afundamento":
        atualizarEstatisticas("afundamento", duracao);
        break;

    case "Sobretensão":
        atualizarEstatisticas("sobretensao", duracao);
        break;

    case "Transitório":
        atualizarEstatisticas("transitorio", duracao);
        break;

    case "Harmônica":
        atualizarEstatisticas("harmonica", duracao);
        break;
}

    historico = historico.slice(0,20);

    flow.set("historico", historico);

    context.set("eventoAtual", null);

    msg.payload = historico;

    return msg;
}

// Atualiza a tabela ao abrir o dashboard
msg.payload = historico;

return msg;

// Calcula total de eventos
var totalEventos =
    (flow.get("qtd_afundamento") || 0) +
    (flow.get("qtd_sobretensao") || 0) +
    (flow.get("qtd_transitorio") || 0) +
    (flow.get("qtd_harmonica") || 0);

// Calcula tempo total
var tempoTotal =
    (flow.get("tempo_afundamento") || 0) +
    (flow.get("tempo_sobretensao") || 0) +
    (flow.get("tempo_transitorio") || 0) +
    (flow.get("tempo_harmonica") || 0);

// Descobre o maior evento
var maiorEvento = "";
var maiorDuracao = 0;

[
    ["Afundamento","maior_afundamento"],
    ["Sobretensão","maior_sobretensao"],
    ["Transitório","maior_transitorio"],
    ["Harmônica","maior_harmonica"]
].forEach(function(e){

    var valor = flow.get(e[1]) || 0;

    if(valor > maiorDuracao){
        maiorDuracao = valor;
        maiorEvento = e[0];
    }

});

// Calcula porcentagens
var percAfundamento =
    totalEventos ? ((flow.get("qtd_afundamento")||0)/totalEventos*100).toFixed(1) : 0;

var percSobretensao =
    totalEventos ? ((flow.get("qtd_sobretensao")||0)/totalEventos*100).toFixed(1) : 0;

var percTransitorio =
    totalEventos ? ((flow.get("qtd_transitorio")||0)/totalEventos*100).toFixed(1) : 0;

var percHarmonica =
    totalEventos ? ((flow.get("qtd_harmonica")||0)/totalEventos*100).toFixed(1) : 0;

var horas = Math.floor(tempoTotal / 3600);
var minutos = Math.floor((tempoTotal % 3600) / 60);
var segundos = Math.floor(tempoTotal % 60);

var tempoFormatado =
    (horas > 0 ? horas + " h " : "") +
    minutos.toString().padStart(2, "0") + " min " +
    segundos.toString().padStart(2, "0") + " s";

// Só agora monta o payload
msg.payload = {

    resumo:{
        total: totalEventos,
        tempoTotal: tempoFormatado,
        maiorEvento: maiorEvento,
        maiorDuracao: maiorDuracao.toFixed(2)
    },

    afundamento:{
        qtd: flow.get("qtd_afundamento") || 0,
        media: ((flow.get("tempo_afundamento")||0) /
               Math.max(flow.get("qtd_afundamento")||1,1)).toFixed(2),
        maior: (flow.get("maior_afundamento")||0).toFixed(2),
        porcentagem: percAfundamento
    },

    sobretensao:{
        qtd: flow.get("qtd_sobretensao") || 0,
        media: ((flow.get("tempo_sobretensao")||0) /
               Math.max(flow.get("qtd_sobretensao")||1,1)).toFixed(2),
        maior: (flow.get("maior_sobretensao")||0).toFixed(2),
        porcentagem: percSobretensao
    },

    transitorio:{
        qtd: flow.get("qtd_transitorio") || 0,
        media: ((flow.get("tempo_transitorio")||0) /
               Math.max(flow.get("qtd_transitorio")||1,1)).toFixed(2),
        maior: (flow.get("maior_transitorio")||0).toFixed(2),
        porcentagem: percTransitorio
    },

    harmonica:{
        qtd: flow.get("qtd_harmonica") || 0,
        media: ((flow.get("tempo_harmonica")||0) /
               Math.max(flow.get("qtd_harmonica")||1,1)).toFixed(2),
        maior: (flow.get("maior_harmonica")||0).toFixed(2),
        porcentagem: percHarmonica
    }

};

return msg;

// =====================================
// TEMPO ATÉ ATUAÇÃO
// =====================================

if (msg.inicioAtuacao) {

    var tempoAtuacao =
        (Date.now() - msg.inicioAtuacao) / 1000;

    msg.tempoAtuacao = tempoAtuacao.toFixed(2);

    // Valor que será mostrado no dashboard
    msg.payload = msg.tempoAtuacao + " s";

} else {

    // Quando não houve atuação
    msg.tempoAtuacao = "0.00";
    msg.payload = "0.00 s";
}

return msg;

// =====================================
// RESET DO TRIP / TEMPORIZADOR
// =====================================

if (msg.trip === false) {

    // Libera uma nova atuação
    context.set("tripAnterior", false);

    // Comando para reiniciar o Relé Temporizado
    msg.reset = true;

    // Saída 2 → Reset Temporizador
    return [null, msg];
}


// =====================================
// DETECÇÃO DO TRIP
// =====================================

var tripAtual = (msg.trip === true);
var tripAnterior = context.get("tripAnterior") || false;


// =====================================
// NOVA ATUAÇÃO
// =====================================

if (tripAtual && !tripAnterior) {

    // Marca o início da atuação
    msg.inicioAtuacao = Date.now();

    context.set("tripAnterior", true);

    // Saída 1 → Relé Temporizado
    return [msg, null];
}


// =====================================
// MANTÉM ESTADO
// =====================================

context.set("tripAnterior", tripAtual);

return null;
